dialog.addEventListener('pointercancel',cleanDrag);dialog.addEventListener('lostpointercapture',()=>{if(drag&&!drag.ghost)cleanDrag();});window.addEventListener('pagehide',()=>{clearInterval(timer);cleanDrag();});
// Continue a paused in-memory local match instead of losing it when the popup closes.
$('#practice').addEventListener('click',event=>{if(!game||game.over||phase==='idle')return;if(!dialog.open){event.preventDefault();if(!dialog.open)dialog.showModal();document.body.classList.add('playing');mobileLayout();paint();if(phase==='paused')handoff('잠깐 쉬는 중','계속하기를 누르면 이어서 플레이합니다.','PAUSED');}},{capture:true});

function receiveRemote(view,{force=false,error=''}={}){
 if(!onlineMode||!view?.game)return;
 const key=view.id+':'+view.round+':'+view.game.turn,own=view.game.currentId===view.viewerId,preserve=remoteTurn===key&&own&&game&&!force&&view.phase==='running';
 remoteRoom=view;remoteOffset=view.serverTime-Date.now();practice=false;limit=60000;remaining=Math.max(0,(view.deadline||Date.now())-Date.now()-remoteOffset);
 if(preserve){consumeTime();return;}
 if(!preserve){
  clearTimeout(draftTimer);selected=[];cleanDrag();onlineSaving=false;
  const players=view.game.players.map(p=>({...p,rack:p.id===view.viewerId?[...view.game.baseRack]:Array(p.count).fill(null)})),self=players.findIndex(p=>p.id===view.viewerId);
  game=restoreGame({players,current:self,pool:Array(view.game.poolCount).fill(null),table:view.game.baseTable,original:{table:view.game.baseTable,rack:view.game.baseRack},draft:{table:view.game.table,rack:view.game.rack},turn:view.game.turn,nextGroup:view.game.nextGroup,history:[],over:view.phase==='finished',result:view.game.result});game.sort(remoteSort);
 }
 phase=view.phase==='finished'?'over':own?'playing':'watching';remoteTurn=key;flash=error;flashKind=error?'error':'';toggleResult(view.phase==='finished');
 document.body.dataset.online='true';dialog.dataset.online='true';$('#handoff').hidden=true;$('#new-game').hidden=true;$('#game-title').innerHTML='루미큐브';
 if(!dialog.open){mobileLayout();dialog.showModal();document.body.classList.add('playing');}
 paint();$('#close-game').disabled=false;toggleResult(view.phase==='finished');if(view.phase==='finished'){renderRoundResult(resultPanel,view,{error,force});$('#coach').textContent='경기 결과';}for(const p of $('#players').children){const index=Number(p.querySelector('.avatar').textContent)-1;p.toggleAttribute('data-current',playersId(index)===view.game.currentId);}
 function playersId(index){return view.game.players[index]?.id;}
}
if(onlineMode){
 document.body.dataset.online='true';
 $('.help-note').textContent='다른 탭·앱으로 이동하거나 경기 화면을 닫아도 턴 시간은 계속 흐릅니다.';
 window.addEventListener('message',event=>{if(event.source!==parent||event.origin!==location.origin||event.data?.type!=='rummi-snapshot')return;receiveRemote(event.data.room,{force:!!event.data.force,error:event.data.error||''});});
 parent.postMessage({type:'rummi-ready'},location.origin);
}
